package android.net.wifi;public class WifiManager{public static int held;public MulticastLock createMulticastLock(String tag){return new MulticastLock();}public static class MulticastLock{boolean acquired;public void setReferenceCounted(boolean flag){}public void acquire(){if(!acquired){acquired=true;held++;}}public void release(){if(acquired){acquired=false;held--;}}public boolean isHeld(){return acquired;}}}
